using System.Collections.Generic;
using UnityEngine;

namespace CourierRunner
{
    /// <summary>
    /// Builds the gold coin mesh in code: a turned disc with a raised rim and a recessed face,
    /// plus a raised five-pointed star on both faces. The coin's faces point along ±Y.
    /// </summary>
    public static class CoinMesh
    {
        private const int Segments = 40;
        private static Mesh body;
        private static Mesh star;

        /// <summary>Disc with a bevelled rim, generated by revolving a profile around Y.</summary>
        public static Mesh Body
        {
            get
            {
                if (body != null) return body;
                // Profile from the center of the top face, over the rim, down the edge and back to the bottom center.
                var profile = new List<Vector2>
                {
                    new(0f, 0.045f), new(0.3f, 0.045f), new(0.33f, 0.07f), new(0.4f, 0.07f), new(0.43f, 0.045f),
                    new(0.43f, -0.045f), new(0.4f, -0.07f), new(0.33f, -0.07f), new(0.3f, -0.045f), new(0f, -0.045f),
                };
                body = Lathe(profile, "Coin Body");
                return body;
            }
        }

        /// <summary>Two extruded stars, one on each face.</summary>
        public static Mesh Star
        {
            get
            {
                if (star != null) return star;
                star = new Mesh { name = "Coin Star" };
                var vertices = new List<Vector3>();
                var triangles = new List<int>();
                AddStar(vertices, triangles, 0.045f, 0.03f, 1f);
                AddStar(vertices, triangles, -0.045f, 0.03f, -1f);
                star.SetVertices(vertices);
                star.SetTriangles(triangles, 0);
                star.RecalculateNormals();
                star.RecalculateBounds();
                return star;
            }
        }

        private static Mesh Lathe(List<Vector2> profile, string name)
        {
            var vertices = new List<Vector3>();
            var triangles = new List<int>();
            // Each profile edge becomes its own ring of quads so the bevels keep hard edges.
            for (int p = 0; p < profile.Count - 1; p++)
            {
                int start = vertices.Count;
                for (int s = 0; s <= Segments; s++)
                {
                    float angle = s * Mathf.PI * 2f / Segments;
                    float cos = Mathf.Cos(angle), sin = Mathf.Sin(angle);
                    vertices.Add(new Vector3(profile[p].x * cos, profile[p].y, profile[p].x * sin));
                    vertices.Add(new Vector3(profile[p + 1].x * cos, profile[p + 1].y, profile[p + 1].x * sin));
                }
                for (int s = 0; s < Segments; s++)
                {
                    int a = start + s * 2;
                    triangles.AddRange(new[] { a, a + 2, a + 1, a + 1, a + 2, a + 3 });
                }
            }
            var mesh = new Mesh { name = name };
            mesh.SetVertices(vertices);
            mesh.SetTriangles(triangles, 0);
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static void AddStar(List<Vector3> vertices, List<int> triangles, float baseY, float height, float facing)
        {
            const int points = 5;
            const float outer = 0.2f, inner = 0.085f;
            var outline = new Vector2[points * 2];
            for (int i = 0; i < outline.Length; i++)
            {
                float angle = Mathf.PI * 0.5f + i * Mathf.PI / points;
                float radius = i % 2 == 0 ? outer : inner;
                outline[i] = new Vector2(Mathf.Cos(angle) * radius, Mathf.Sin(angle) * radius);
            }
            float topY = baseY + height * facing;

            // Raised top: a fan around the center.
            int center = vertices.Count;
            vertices.Add(new Vector3(0f, topY, 0f));
            for (int i = 0; i < outline.Length; i++) vertices.Add(new Vector3(outline[i].x, topY, outline[i].y));
            for (int i = 0; i < outline.Length; i++)
            {
                int a = center + 1 + i, b = center + 1 + (i + 1) % outline.Length;
                if (facing > 0f) triangles.AddRange(new[] { center, b, a });
                else triangles.AddRange(new[] { center, a, b });
            }

            // Side walls between the face and the star top.
            for (int i = 0; i < outline.Length; i++)
            {
                Vector2 p0 = outline[i], p1 = outline[(i + 1) % outline.Length];
                int s = vertices.Count;
                vertices.Add(new Vector3(p0.x, baseY, p0.y));
                vertices.Add(new Vector3(p1.x, baseY, p1.y));
                vertices.Add(new Vector3(p0.x, topY, p0.y));
                vertices.Add(new Vector3(p1.x, topY, p1.y));
                if (facing > 0f) triangles.AddRange(new[] { s, s + 2, s + 1, s + 1, s + 2, s + 3 });
                else triangles.AddRange(new[] { s, s + 1, s + 2, s + 1, s + 3, s + 2 });
            }
        }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetStatics()
        {
            body = null;
            star = null;
        }
    }
}
